// 수동 입력 JSON만 허용한다. claim 전 원 실행 종료·Jira 효과를 운영자가 대조한다.
let payload = null;
try { payload = JSON.parse($json.payload); } catch {}
const obj = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const text = v => typeof v === 'string' && v.trim().length > 0;
const common = ['op','scope','dlq_id','operator_id'];
const extras = {
  inspect: [],
  finish: ['expected_dlq_revision','expected_state_revision','original_execution_id','recovery_execution_id','verification'],
  claim: ['owner_id','input_hash','expected_dlq_revision','expected_state_revision','original_execution_id','recovery_execution_id','verification'],
  resume: ['owner_id','input_hash','expected_dlq_revision','expected_state_revision','original_execution_id','recovery_execution_id','verification'],
  complete: ['owner_id','input_hash','expected_dlq_revision','expected_state_revision','original_execution_id','recovery_execution_id','jira_issue_id','jira_issue_key','response','effects','verification'],
  release: ['owner_id','input_hash','expected_dlq_revision','expected_state_revision','original_execution_id','recovery_execution_id','reason','verification','target_effect_status'],
};
const required = obj(payload) && extras[payload.op] ? [...common, ...extras[payload.op]] : [];
const allowed = new Set(required);
const validKeys = required.length > 0 && Object.keys(payload).length === allowed.size && Object.keys(payload).every(k => allowed.has(k));
const ids = text(payload?.original_execution_id) && text(payload?.recovery_execution_id) && payload.original_execution_id !== payload.recovery_execution_id;
const revisions = Number.isInteger(payload?.expected_dlq_revision) && payload.expected_dlq_revision >= 0 && Number.isInteger(payload?.expected_state_revision) && payload.expected_state_revision >= 0;
const valid = validKeys && text(payload.scope) && text(payload.dlq_id) && text(payload.operator_id)
  && (payload.op === 'inspect' || (ids && revisions && (payload.op === 'finish'
    ? payload.verification === 'jira_effects_confirmed'
    : payload.op === 'claim'
      ? text(payload.owner_id) && /^[0-9a-f]{64}$/.test(payload.input_hash) && ['recovery_conditions_confirmed','recovery_unknown_effect_checked_absent','recovery_unknown_effect_checked_present'].includes(payload.verification)
      : payload.op === 'resume'
        ? text(payload.owner_id) && /^[0-9a-f]{64}$/.test(payload.input_hash) && payload.verification === 'recovery_conditions_confirmed'
        : payload.op === 'complete'
          ? text(payload.owner_id) && /^[0-9a-f]{64}$/.test(payload.input_hash) && text(payload.jira_issue_id) && /^JBYS-[0-9]+$/.test(payload.jira_issue_key) && obj(payload.response) && obj(payload.effects) && payload.verification === 'recovery_action_effects_confirmed'
          : text(payload.owner_id) && /^[0-9a-f]{64}$/.test(payload.input_hash) && text(payload.reason) && payload.reason.length <= 200 && payload.verification === 'recovery_execution_ended_and_effects_rechecked' && (payload.target_effect_status === 'none' || ['failed','unknown','confirmed'].includes(payload.target_effect_status)))));
return { json: { valid, payload: valid ? payload : null, error_code: valid ? null : 'invalid_operator_recovery_request' } };
